funkin_save_Save.loadFromSlot = function(slot) {
	haxe_Log.trace("[SAVE] Loading save from slot " + slot + "...",{ fileName : "source/funkin/save/Save.hx", lineNumber : 772, className : "funkin.save.Save", methodName : "loadFromSlot"});
	flixel_FlxG.save.bind("Funkin" + slot,"FunkinCrew");
	switch(flixel_FlxG.save.status._hx_index) {
	case 0:
		haxe_Log.trace("[SAVE] Save data in slot " + slot + " is empty, checking for legacy save data...",{ fileName : "source/funkin/save/Save.hx", lineNumber : 777, className : "funkin.save.Save", methodName : "loadFromSlot"});
		var _g = funkin_save_Save.system.fetchLegacySaveData();
		switch(_g._hx_index) {
		case 0:
			haxe_Log.trace("[SAVE] Found legacy save data, converting...",{ fileName : "source/funkin/save/Save.hx", lineNumber : 786, className : "funkin.save.Save", methodName : "loadFromSlot"});
			var gameSave = funkin_save_migrator_SaveDataMigrator.migrateFromLegacy(_g.v);
			flixel_FlxG.save.mergeData(gameSave.data,true);
			return gameSave;
		case 1:
			haxe_Log.trace("[SAVE] No legacy save data found.",{ fileName : "source/funkin/save/Save.hx", lineNumber : 781, className : "funkin.save.Save", methodName : "loadFromSlot"});
			var gameSave = new funkin_save_Save();
			flixel_FlxG.save.mergeData(gameSave.data,true);
			return gameSave;
		}
		break;
	case 1:
		haxe_Log.trace("[SAVE] Loaded existing save data in slot " + slot + ".",{ fileName : "source/funkin/save/Save.hx", lineNumber : 798, className : "funkin.save.Save", methodName : "loadFromSlot"});
		var gameSave = funkin_save_migrator_SaveDataMigrator.migrate(flixel_FlxG.save.data);
		flixel_FlxG.save.mergeData(gameSave.data,true);
		return gameSave;
	case 2:
		return funkin_save_Save.handleSaveDataError(slot);
	case 3:
		return funkin_save_Save.handleSaveDataError(slot);
	case 4:
		return funkin_save_Save.handleSaveDataError(slot);
	}
};
funkin_save_Save.handleSaveDataError = function(slot) {
	var msg = "There was an error loading your save data in slot " + slot + ".";
	msg += "\nPlease report this issue to the developers.";
	funkin_util_WindowUtil.showError("Save Data Failure",msg);
	var nextSlot = slot + 1;
	if(nextSlot > 1000) {
		throw haxe_Exception.thrown("End of save data slots. Can't load any more.");
	}
	return funkin_save_Save.loadFromSlot(nextSlot);
};
funkin_save_Save.saveToNewgrounds = function() {
	if(funkin_save_Save._instance == null) {
		return;
	}
	haxe_Log.trace("[SAVE] Saving Save Data to Newgrounds...",{ fileName : "source/funkin/save/Save.hx", lineNumber : 913, className : "funkin.save.Save", methodName : "saveToNewgrounds"});
	funkin_api_newgrounds_NGSaveSlot.get_instance().save(funkin_save_Save._instance.data);
};
funkin_save_Save.loadFromNewgrounds = function(onFinish) {
	haxe_Log.trace("[SAVE] Loading Save Data from Newgrounds...",{ fileName : "source/funkin/save/Save.hx", lineNumber : 919, className : "funkin.save.Save", methodName : "loadFromNewgrounds"});
	funkin_api_newgrounds_NGSaveSlot.get_instance().load(function(data) {
		flixel_FlxG.save.bind("Funkin" + 1,"FunkinCrew");
		if(flixel_FlxG.save.status != flixel_util_FlxSaveStatus.EMPTY) {
			haxe_Log.trace("[SAVE] Backed up current save data in case of emergency to " + funkin_save_Save.system.archiveBadSaveData(flixel_FlxG.save.data) + "!",{ fileName : "source/funkin/save/Save.hx", lineNumber : 929, className : "funkin.save.Save", methodName : "loadFromNewgrounds"});
		}
		flixel_FlxG.save.erase();
		flixel_FlxG.save.bind("Funkin" + 1,"FunkinCrew");
		var gameSave = funkin_save_migrator_SaveDataMigrator.migrate(data);
		flixel_FlxG.save.mergeData(gameSave.data,true);
		funkin_save_Save._instance = gameSave;
		onFinish();
	},function(error) {
		var msg = "There was an error loading your save data from Newgrounds.";
		msg = "There was an error loading your save data from Newgrounds." + ("\n" + io_newgrounds_CallErrorTools.toString(error));
		msg += "\nAre you sure you are connected to the internet?";
		funkin_util_WindowUtil.showError("Newgrounds Save Slot Failure",msg);
	});
};
